from lib import *
S = SS('g81')
steps = [
    step("io.Copy 的缓冲区:两边都只暴露 Read / Write 时,把 1 MiB 拷过去调用 Read 33 次,每次传入的缓冲区长度是 32768。目标换成 io.Discard(它自带 ReadFrom)时,Read 129 次,缓冲区长度 8192。io.CopyBuffer 传 4096 字节的缓冲区:Read 257 次。源是 io.LimitReader:限 100 字节时每次 io.Copy 分配 200 B,限 1 MiB 时每次分配 32856 B——缓冲区会按 LimitedReader.N 缩小。", t=tl(S(1)), done=lidx(S(1), '调用 Read 33 次', 'io.CopyBuffer'), mark=lidx(S(1), '目标换成 io.Discard', '源是 io.LimitReader'), b=bars([['默认缓冲区 (字节)', 32768, '32768'], ['io.Discard 的 ReadFrom', 8192, '8192'], ['CopyBuffer 自备', 4096, '4096']], 32768, done=[0, 2], mark=[1]), kv=KV([['默认', '32 KiB 缓冲区,1 MiB 要 33 次 Read'], ['目标是 io.Discard', '走 ReadFrom,8 KiB 缓冲区'], ['源是 LimitReader', '缓冲区缩到 N']], ['目标是 io.Discard'])),
    step("io.Copy 怎么挑实现:源实现了 WriterTo,io.Copy 调用了 WriteTo 1 次、Read 0 次;目标实现了 ReaderFrom、源只有 Read:ReadFrom 1 次,Write 0 次;两边都只暴露 Read / Write:ReadFrom 0 次,Write 32 次(1 MiB ÷ 32 KiB)。拷到 io.Discard:源是 *bytes.Reader(有 WriteTo)每次 1 次分配,包成只有 Read 的 struct 后每次 2 次分配。", t=tl(S(2)), done=lidx(S(2), '源实现了 WriterTo', '目标实现了 ReaderFrom'), mark=lidx(S(2), '两边都只暴露', '拷到 io.Discard'), kv=KV([['源有 WriteTo', '优先走 WriteTo'], ['目标有 ReadFrom', '其次走 ReadFrom'], ['都没有', '32 KiB 缓冲区循环 Read/Write'], ['分配', '走接口 1 次,不走 2 次']], ['源有 WriteTo'])),
    step("真实文件与 TCP(256 MiB,两种写法交替各跑 3 轮取中位数):文件到文件:io.Copy(*os.File, *os.File) 83 ms(3103 MiB/s),包一层隐藏 ReaderFrom / WriterTo 后 79 ms(3261 MiB/s)——这台 macOS 上没有差别;读文件算 SHA-256:io.Copy(hash, file) 127 ms,经 TeeReader 144 ms;文件到本机 TCP:io.Copy(*net.TCPConn, *os.File) 57 ms(4506 MiB/s),隐藏接口后 109 ms(2357 MiB/s),约慢一倍。", t=tl(S(3)), done=lidx(S(3), '文件到本机 TCP', '读 256 MiB 文件算 SHA-256'), mark=lidx(S(3), '文件到文件'), b=bars([['文件→TCP,io.Copy (ms)', 57, '57'], ['文件→TCP,隐藏接口', 109, '109'], ['文件→文件,io.Copy', 83, '83'], ['文件→文件,隐藏接口', 79, '79']], 109, done=[0, 2, 3], mark=[1]), kv=KV([['文件→TCP', '57 vs 109 ms:接口让它快一倍'], ['文件→文件', '83 vs 79 ms:这里没差别'], ['TeeReader', '多一层约 +13%']], ['文件→TCP'])),
    step("io.Copy 的文档:从 src 拷到 dst 直到 src 的 EOF 或出错;成功的 Copy 返回 err == nil 而不是 EOF;如果 src 实现了 WriterTo,就调用 src.WriteTo(dst);否则如果 dst 实现了 ReaderFrom,就调用 dst.ReadFrom(src)。", t=tl(S(4)), done=lidx(S(4), 'src implements WriterTo'), mark=lidx(S(4), 'EOF'), kv=KV([['优先级', 'WriterTo > ReaderFrom > 缓冲区循环'], ['返回', '成功时 err == nil,不是 EOF']], ['优先级'])),
]
A = mkartg('g81', 81, 'Go,io.Copy,io.Reader,io.Writer,WriterTo,ReaderFrom,真实验证,动画演示',
    '在 Go 1.27.1(arm64 macOS)里验证 io.Copy:默认 32 KiB 缓冲区,目标是 io.Discard 时因为它自带 ReadFrom 变成 8 KiB;优先走 WriterTo、其次 ReaderFrom、最后才是缓冲区循环;文件到 TCP 走接口 57 ms,隐藏接口后 109 ms,而文件到文件在这台机器上没有差别(83 对 79 ms);LimitReader 会把缓冲区缩小。',
    'io.Copy 看起来只是一个读写循环,实际上先看两端有没有实现 WriterTo / ReaderFrom。这篇用计数包装、分配统计和真实文件/TCP 拷贝验证它怎么选实现、缓冲区多大,以及隐藏接口会付出多少代价。',
    [('32768 / 8192', 'io.Copy 默认缓冲区大小,目标是 io.Discard 时变成 8192'), ('57 vs 109 ms', '256 MiB 从文件拷到本机 TCP 连接,用接口与隐藏接口'), ('83 vs 79 ms', '文件到文件,这台 macOS 上两种写法没有差别')],
    [('缓冲区', '<p>两边都只有 <code>Read</code>/<code>Write</code> 时,<code>io.Copy</code> 用 32 KiB 缓冲区,1 MiB 要 33 次 <code>Read</code>;如果目标是 <code>io.Discard</code>,它自带 <code>ReadFrom</code>,变成 8 KiB 缓冲区,129 次。源是 <code>io.LimitReader</code> 时缓冲区会缩小到限制值,限 100 字节时每次 <code>io.Copy</code> 只分配 200 B。</p>'),
     ('挑实现的顺序', '<p>源有 <code>WriterTo</code> 就用 <code>WriteTo</code>;否则目标有 <code>ReaderFrom</code> 就用 <code>ReadFrom</code>;都没有才自己循环。给 <code>*bytes.Reader</code> 套一层 <code>struct{io.Reader}</code> 就把 <code>WriteTo</code> 藏起来了,分配也从 1 次变成 2 次。</p>'),
     ('这条路径值多少', '<p>文件到本机 TCP,走 <code>*net.TCPConn</code> 的 <code>ReadFrom</code> 只要 57 ms(4506 MiB/s),包一层隐藏后 109 ms。文件到文件在这台 macOS 上两种写法都是约 80 ms,没有差别。第一次测的时候我没有交替运行,得到过 254 对 177 ms 的“差距”,那是顺序和缓存的影响;交替运行后消失了。<code>TeeReader</code> 多包一层来算 SHA-256,耗时多了约 13%。</p>'),
     ('读文档', '<p>文档写明:src 有 <code>WriterTo</code> 就调用它,否则 dst 有 <code>ReaderFrom</code> 就调用它;成功时返回 <code>err == nil</code> 而不是 <code>EOF</code>。写自己的类型时,包装 reader/writer 要想想是否因此失去了这些快速路径。</p>')],
    steps,
    [ENV_G + '。读调用次数与缓冲区长度由包装 Read 的计数器记录;分配用 testing.AllocsPerRun / Benchmark 的 B/op;文件与 TCP 实验用 256 MiB 临时文件(实验后已删除),本机回环 TCP;每种写法交替各 3 轮,每轮 5 次取中位数,再取 3 轮的中位数;读过的源码与文档:src/io/io.go 的 copyBuffer,go doc io.Copy',
     '没有验证:Linux 上的 splice/copy_file_range/sendfile 行为(macOS 上的结果不能直接套用)、磁盘缓存冷启动时的文件拷贝、io.Pipe、MultiWriter 的开销、ReadFrom 在不同 Go 版本里的实现差别'],
    'io.Reader 与 io.Writer')
